/* Login must not wait for optional CDN exports/fonts; bound unbounded Supabase reads. */
(function(){'use strict';const native=window.fetch;window.fetch=function(input,options={}){const url=typeof input==='string'?input:input?.url;if(!/^https:\/\/[\w-]+\.supabase\.co\/(rest|auth)\/v1\//.test(url||'')||options.signal||input?.signal)return native.call(this,input,options);const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);return native.call(this,input,{...options,signal:controller.signal}).catch(e=>{if(controller.signal.aborted)throw Error('Waktu koneksi Supabase habis (45 detik). Periksa jaringan lalu tekan Muat ulang.');throw e}).finally(()=>clearTimeout(timer));};
let stopped=false,timer,watch;function done(){stopped=true;clearTimeout(timer);watch?.disconnect();document.getElementById('boot-status-v68')?.remove()}
function mount(){if(stopped)return;const box=document.createElement('section');box.id='boot-status-v68';box.setAttribute('role','status');box.style.cssText='position:fixed;inset:0;z-index:999999;background:#f4f6fc;color:#23324c;display:grid;place-content:center;gap:14px;padding:24px;font:15px/1.6 system-ui';const text=document.createElement('p');text.textContent='Menyiapkan halaman login…';box.append(text);document.body.append(box);watch=new MutationObserver(()=>{if(document.getElementById('login-v38'))done()});watch.observe(document.body,{subtree:true,childList:true});if(document.getElementById('login-v38')){done();return}timer=setTimeout(()=>{text.textContent='Halaman belum selesai dimuat. Periksa koneksi atau file pembaruan aplikasi.';const button=document.createElement('button');button.textContent='Coba muat ulang';button.onclick=()=>location.reload();box.append(button)},20000);}
window.addEventListener('error',e=>{if(stopped)return;const p=document.querySelector('#boot-status-v68 p');if(p)p.textContent='Pemuatan aplikasi terhenti. Pastikan seluruh file pembaruan sudah diunggah, lalu muat ulang.';},true);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
// Existing sessions can bypass the login gate; finish once data loading has rendered a result.
const check=setInterval(()=>{if(stopped){clearInterval(check);return}if(document.querySelector('#login-v38')||document.querySelector('.page.on .phead')&&['Terhubung','Gagal terhubung'].includes(document.querySelector('#conn')?.textContent)){done();clearInterval(check)}},300);setTimeout(()=>clearInterval(check),120000);
})();
